"""Choix d'une piste YouTube Music (top.choix_music), sans réseau.
Lancer : python -m unittest discover tests"""
import os
import sys
import unittest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import top  # noqa: E402


def piste(titre, duree, vues=1000, album="", auto=True, chaine="Renan Luce"):
    return {"id": f"{titre}-{duree}", "title": titre, "duration": duree, "view_count": vues, "album": album,
            "channel": chaine, "description": "Auto-generated by YouTube" if auto else ""}


def choisir(resultats, titre="Le lacrymal circus", duree=226, artiste="Renan Luce"):
    fiches = {r["id"]: r for r in resultats}
    return top.choix_music(artiste, titre, duree)(resultats, lambda r: fiches.get(r["id"]))


class ChoixMusic(unittest.TestCase):
    def test_master_un_peu_different_de_deezer_accepte(self):
        # Deezer 226 s, YouTube 232 s : même piste officielle, autre master
        self.assertEqual(232, choisir([piste("Le lacrymal circus", 232)])["duration"])

    def test_ecart_trop_grand_refuse(self):
        self.assertIsNone(choisir([piste("Le lacrymal circus", 226 + top.TOLERANCE_DUREE_MUSIC + 1)]))

    def test_piste_non_officielle_refusee_meme_proche(self):
        self.assertIsNone(choisir([piste("Le lacrymal circus", 232, auto=False, chaine="Quelqu'un")]))

    def test_live_toujours_refuse(self):
        self.assertIsNone(choisir([piste("Le lacrymal circus (Live)", 226)]))

    def test_duree_deezer_preferee_a_la_plus_ecoutee(self):
        pistes = [piste("Le lacrymal circus", 233, vues=900000), piste("Le lacrymal circus", 227, vues=10)]
        self.assertEqual(227, choisir(pistes)["duration"])

    def test_a_duree_egale_la_plus_ecoutee(self):
        pistes = [piste("Le lacrymal circus", 226, vues=10), piste("Le lacrymal circus", 227, vues=500)]
        self.assertEqual(500, choisir(pistes)["view_count"])


if __name__ == "__main__":
    unittest.main()
